<script lang="ts">
 import {atlasArticles,enrichAtlasArticle} from '#lib/atlas-content.ts';import {searchText} from '#lib/search.ts';
 import ArticleBody from '#lib/components/learning/ArticleBody.svelte';
 import ImageFocus from '#lib/components/ImageFocus.svelte';
 import {onMount}from'svelte';import{beforeNavigate}from'$app/navigation';import{session,api,ui}from'#lib/client.svelte.ts';import{editorial,loadEditorial,getArticles,getWines,getHome,imageSrc,creditFor}from'#lib/editorial.svelte.ts';import Modal from'#lib/components/Modal.svelte';import Icon from'#lib/components/Icon.svelte';
 let tab=$state('tastings');let articleSearch=$state('');let rooms=$state<any[]>([]);let key=$state('article:pfalz');let draft=$state<any>(null);let initial=$state('');let version=$state(0);let busy=$state(false);let error=$state('');let notice=$state('');let media=$state<any[]>([]);let picker=$state(false);let uploadAlt=$state('');let uploadCredit=$state('');let uploadSource=$state('');let uploadFile:HTMLInputElement;let imageField=$state('image');let loaded=$state(false);let loading=$state(false);
 const dirty=$derived(!!draft&&JSON.stringify(draft)!==initial);const kind=$derived(key.split(':')[0]);const field=$derived(kind==='article'?'image':kind==='wine'?'bottleImage':'heroImage');const prefix=$derived(kind==='article'?'image':kind==='wine'?'bottle':'hero');let paragraphText=$state('');let hostText=$state('');const libraryArticles=$derived(getArticles(atlasArticles).map(enrichAtlasArticle));const selectableArticles=$derived(libraryArticles.filter(a=>'article:'+a.slug===key||searchText(a.title+' '+a.eyebrow+' '+a.category+' '+(a.aliases||[]).join(' ')).includes(searchText(articleSearch.trim()))));
 function select(next:string,force=false){if(!force&&dirty&&!confirm('Du hast ungespeicherte Änderungen. Verwerfen?'))return;key=next;const id=next.split(':')[1];const a=next.startsWith('article:')?getArticles(atlasArticles).map(enrichAtlasArticle).find(a=>a.slug===id):undefined;const w=next.startsWith('wine:')?getWines().find(w=>w.id===id):undefined;const base=a?{countries:a.countries,aliases:a.aliases,...(a.atlas?{atlas:a.atlas}:{}),title:a.title,eyebrow:a.eyebrow,intro:a.intro,paragraphs:a.paragraphs,sections:a.sections||[],visual:a.visual||'none',host:a.host,fact:a.fact,image:imageSrc(a.image),imagePosition:a.imagePosition||'center center',imagePositionMobile:a.imagePositionMobile||a.imagePosition||'center center',imageFit:a.imageFit||'cover',imageAlt:a.imageAlt||'',imageCredit:creditFor(a).text,imageSource:creditFor(a).url,sources:a.sources}:w?{name:w.name,producer:w.producer,region:w.region,grape:w.grape,style:w.style,hint:w.hint,bottleImage:w.bottleImage||'',bottleAlt:w.bottleAlt||'',bottleCredit:w.bottleCredit||'',bottleSource:w.bottleSource||'',bottleNote:w.bottleNote||''}:getHome();draft=JSON.parse(JSON.stringify(base));paragraphText=draft.paragraphs?.join('\n\n')||'';hostText=draft.host?.join('\n\n')||'';initial=JSON.stringify(draft);version=editorial.records[next]?.version||0;notice='';error='';}
 async function load(){loading=true;try{await loadEditorial(true);rooms=(await api('admin/rooms')).rooms;media=(await api('admin/media')).media;select(key,true);loaded=true;}catch(e){error=(e as Error).message;}finally{loaded=true;loading=false;}}
 onMount(()=>{const guard=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',guard);return()=>window.removeEventListener('beforeunload',guard);});
 $effect(()=>{if(session.loaded&&session.user?.role==='admin'&&!loaded&&!loading)void load();});
 beforeNavigate(({cancel})=>{if(dirty&&!confirm('Du hast ungespeicherte Änderungen. Seite verlassen?'))cancel();});
 function changeTab(next:string){if(dirty&&!confirm('Du hast ungespeicherte Änderungen. Verwerfen?'))return;tab=next;if(next==='articles')select('article:pfalz',true);else if(next==='wines')select('wine:secco',true);else if(next==='home')select('page:home',true);else{draft=null;initial='';}error='';notice='';}
 async function save(){busy=true;error='';notice='';try{const d=await api('admin/content',{key,data:draft,version});editorial.records=d.records;select(key,true);notice='Gespeichert. Die Änderung ist jetzt für alle sichtbar.';}catch(e){error=(e as Error).message;}busy=false;}
 const split=(text:string)=>text.split(/\n\s*\n/).map(t=>t.trim()).filter(Boolean);
 function choose(m:any){draft[imageField]=m.url;const prefix=imageField==='heroImage'?'hero':imageField==='bottleImage'?'bottle':'image';draft[prefix==='image'?'imageAlt':prefix+'Alt']=m.alt;draft[prefix==='image'?'imageCredit':prefix+'Credit']=m.credit;draft[prefix==='image'?'imageSource':prefix+'Source']=m.source;picker=false;}
 async function upload(){const file=uploadFile?.files?.[0];if(!file){error='Wähle zuerst ein Bild aus.';return;}busy=true;error='';try{const form=new FormData();form.set('file',file);form.set('alt',uploadAlt);form.set('credit',uploadCredit);form.set('source',uploadSource);const r=await fetch('/api/admin/media',{method:'POST',body:form});const d=await r.json();if(!r.ok)throw Error(d.error||d.message||'Das Bild konnte nicht hochgeladen werden.');media=[d.media,...media];uploadAlt='';uploadCredit='';uploadSource='';uploadFile.value='';notice='Bild hochgeladen. Wähle es in der Bibliothek aus.';}catch(e){error=(e as Error).message;}busy=false;}
</script>
<svelte:head><title>Host-Bereich · Sip Happens</title><meta name="robots" content="noindex,nofollow"/></svelte:head>
<div class="page-content admin-page">
 <div class="page-heading"><div><div class="eyebrow">HOST-BEREICH</div><h1>Tastings & Inhalte<span class="accent">.</span></h1><p>Hier bereitest du den Abend vor und bearbeitest die App.</p></div>{#if session.user?.role==='admin'}<button class="button primary" onclick={()=>ui.createOpen=true}><Icon name="plus" size={18}/>Tasting erstellen</button>{/if}</div>
 {#if !session.loaded}<p class="muted">Host-Bereich wird geladen …</p>{:else if session.user?.role!=='admin'}<div class="panel"><h2>Als Host anmelden</h2><p>Für die Tasting-Steuerung und die Bearbeitung brauchst du das Host-Konto.</p><a class="button primary" href="/konto?next=/admin">Zum Host-Login<Icon name="right" size={17}/></a></div>{:else}
 {#if !loaded}<p class="muted">Tastings und Inhalte werden geladen …</p>{:else}<nav class="admin-tabs" aria-label="Host-Bereich">{#each [['tastings','Tastings'],['articles','Artikel'],['wines','Weine'],['home','Startseite'],['media','Bilder']] as [id,label]}<button class:active={tab===id} aria-pressed={tab===id} onclick={()=>changeTab(id)}>{label}</button>{/each}</nav>
 {#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice&&!picker}<p class="save-notice" role="status"><Icon name="check" size={17}/>{notice}</p>{/if}
 {#if tab==='tastings'}<div class="admin-room-list">{#each rooms as room}<article class="panel admin-room"><div><span class="small-badge">{room.closed?'Beendet':'Offen'} · {room.participants} {room.participants===1?'Gast':'Gäste'}</span><h2>{room.name}</h2><p class="muted">Code {room.code} · {new Date(room.created_at).toLocaleDateString('de-DE')}</p></div><a class="button outline" href={'/host/'+room.code}>Host-Ansicht<Icon name="right" size={17}/></a></article>{/each}{#if !rooms.length}<div class="empty-state"><h2>Noch kein Tasting</h2><p>Erstelle ein Tasting. In der Host-Ansicht findest du den QR-Code für deine Gäste.</p></div>{/if}</div>
 {:else if tab==='media'}<div class="panel"><h2>Bildbibliothek</h2><p class="muted">Neue Bilder lädst du beim Bearbeiten eines Artikels, Weins oder der Startseite hoch. Dort kannst du sie direkt zuordnen.</p></div><div class="media-grid">{#each media as m}<figure><img src={m.url} alt={m.alt} loading="lazy"/><figcaption><strong>{m.alt}</strong><span>{m.credit}</span></figcaption></figure>{/each}</div>
 {:else if draft}<div class="editor-toolbar">{#if tab==='articles'}<div class="editor-article-picker"><label>Artikel suchen<input type="search" bind:value={articleSearch} placeholder="Region, Rebsorte oder Weingut"/></label><label>Artikel auswählen<select aria-label="Artikel auswählen" value={key} onchange={e=>{select(e.currentTarget.value);e.currentTarget.value=key;}}>{#each selectableArticles as a}<option value={'article:'+a.slug}>{a.category} · {a.title}</option>{/each}</select></label></div>{:else if tab==='wines'}<label>Wein auswählen<select value={key} onchange={e=>{select(e.currentTarget.value);e.currentTarget.value=key;}}>{#each getWines() as w,i}<option value={'wine:'+w.id}>0{i+1} · {w.name}</option>{/each}</select></label>{:else}<p class="muted">Überschrift, Einführung und Titelbild der Startseite</p>{/if}<a class="text-button preview-link" href="#editor-preview">Zur Vorschau<Icon name="right" size={16}/></a><span class="muted small">{dirty?'Ungespeicherte Änderungen':version?'Gespeicherte Fassung '+version:'Originalfassung'}</span></div>
 <form class="editor-layout" onsubmit={e=>{e.preventDefault();save();}}><div class="panel editor-fields">
 {#if kind==='article'}{#if draft.atlas}<details class="editor-details"><summary>Kurzübersicht bearbeiten</summary><div class="editor-profile-facts">{#each draft.atlas.facts as fact}<fieldset><label>Bezeichnung<input bind:value={fact.label} maxlength="120" required/></label><label>Text<input bind:value={fact.value} maxlength="1000" required/></label></fieldset>{/each}{#if draft.atlas.aromas}<label>Duftwörter <small>Mit Komma trennen.</small><input value={draft.atlas.aromas.join(', ')} oninput={e=>draft.atlas.aromas=e.currentTarget.value.split(',').map((v:string)=>v.trim()).filter(Boolean)} maxlength="1000"/></label>{/if}</div></details>{/if}<label>Titel<input bind:value={draft.title} required maxlength="160"/></label><label>Unterzeile<input bind:value={draft.eyebrow} maxlength="160"/></label><label>Einführung<textarea bind:value={draft.intro} rows="3" maxlength="2000"></textarea></label><label>Artikeltext <small>Absätze durch eine Leerzeile trennen.</small><textarea bind:value={paragraphText} oninput={e=>draft.paragraphs=split(e.currentTarget.value)} rows="13"></textarea></label><details class="editor-details"><summary>Vertiefende Abschnitte ({draft.sections.length})</summary><div class="editor-article-sections">{#each draft.sections as section,i}<fieldset class="editor-sources"><legend>Abschnitt {i+1}</legend><label>Zwischenüberschrift<input bind:value={section.title} required maxlength="160"/></label><label>Abschnittstext<textarea bind:value={section.body} rows="6" required maxlength="6000"></textarea></label><button type="button" class="text-button" onclick={()=>draft.sections=draft.sections.filter((_:any,n:number)=>n!==i)}>Abschnitt entfernen</button></fieldset>{/each}<button type="button" class="button outline" disabled={draft.sections.length>=8} onclick={()=>draft.sections=[...draft.sections,{title:'',body:''}]}>Abschnitt hinzufügen</button></div></details><label>Erklärgrafik<select bind:value={draft.visual}>{#if draft.visual==='rose-compare'}<option value="rose-compare">Unsere beiden Rosés vergleichen</option>{/if}{#if draft.atlas}<option value="atlas">Ort und Kurzprofil</option>{/if}{#if draft.visual==='wine-style'}<option value="wine-style">Herstellung im Überblick</option>{/if}{#each [['none','Keine Grafik'],['region','Region auf der Karte'],['producer','Unser Wein'],['skins','Schalenkontakt & Farbe'],['bubbles','Kohlensäure & Druck'],['aromas','Duftfamilien'],['pinot','Pinot-Familie'],['balance','Süße & Säure'],['fermentation','Weinbereitung'],['closures','Verschlüsse'],['temperature','Trinktemperatur'],['label','Etikett lesen'],['storage','Wein aufbewahren']] as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>Gut zu wissen<textarea bind:value={draft.fact} rows="3" maxlength="1200"></textarea></label><label>Hintergrund für den Host <small>Nur im angemeldeten Host-Bereich sichtbar.</small><textarea bind:value={hostText} oninput={e=>draft.host=split(e.currentTarget.value)} rows="12"></textarea></label>
 {:else if kind==='wine'}{#each [['name','Name'],['producer','Weingut / Winzer'],['region','Region'],['grape','Rebsorte(n)'],['style','Weinart & Geschmack'],['vintage','Jahrgang']] as [field,label]}<label>{label}<input bind:value={draft[field]} required={field==='name'||field==='producer'} maxlength={field==='vintage'?20:160}/></label>{/each}<label>Frage zur Verkostung<textarea bind:value={draft.hint} rows="3" maxlength="2000"></textarea></label><label>Hinweis zum Produktfoto<input bind:value={draft.bottleNote} maxlength="400"/></label>
 {:else}<label>Seitenüberschrift<input bind:value={draft.title} required maxlength="160"/></label><label>Einführung<textarea bind:value={draft.intro} rows="3" maxlength="1000"></textarea></label><label>Titel im großen Feld<input bind:value={draft.heroTitle} required maxlength="200"/></label><label>Text im großen Feld<textarea bind:value={draft.heroText} rows="5" maxlength="1600"></textarea></label>{/if}

 <fieldset class="editor-sources"><legend>{kind==='wine'?'Flaschenbild':'Titelbild'}</legend><button type="button" class="button outline" onclick={()=>{imageField=field;picker=true;error='';notice='';}}>Bild auswählen oder hochladen<Icon name="plus" size={16}/></button>{#if draft[field]&&kind!=='wine'}<ImageFocus src={imageSrc(draft[field])} alt={draft[prefix+'Alt']} bind:position={draft[kind==='article'?'imagePosition':'heroPosition']} bind:positionMobile={draft[kind==='article'?'imagePositionMobile':'heroPositionMobile']} bind:fit={draft[kind==='article'?'imageFit':'heroFit']}/>{:else if kind==='wine'}<p class='muted small'>Flaschenbilder werden immer vollständig angezeigt.</p>{/if}<details class='editor-details'><summary>Bildangaben bearbeiten</summary><div class='editor-fields'><label>Bildadresse<input type="text" bind:value={draft[field]} placeholder="https://…"/></label><label>Bildbeschreibung für Screenreader<input bind:value={draft[prefix+'Alt']} maxlength="400"/></label><label>Bildnachweis<input bind:value={draft[prefix+'Credit']} maxlength="400"/></label><label>Quelle des Bildes<input type="url" bind:value={draft[prefix+'Source']}/></label></div></details></fieldset>
 <div class="editor-save"><button class="button primary" disabled={busy||!dirty}>{busy?'Wird gespeichert …':'Änderungen veröffentlichen'}<Icon name="check" size={17}/></button><button type="button" class="text-button" disabled={busy||!dirty} onclick={()=>select(key)}>Verwerfen</button></div></div>
 <aside class="editor-preview" id="editor-preview"><div class="eyebrow">VORSCHAU</div>{#if draft[field]}<img class='editorial-image' class:preview-bottle={kind==='wine'} style={'--image-position:'+(draft[kind==='article'?'imagePosition':'heroPosition']||'center')+';--image-position-mobile:'+(draft[kind==='article'?'imagePositionMobile':'heroPositionMobile']||draft[kind==='article'?'imagePosition':'heroPosition']||'center')+';--image-fit:'+(kind==='wine'?'contain':draft[kind==='article'?'imageFit':'heroFit']||'cover')} src={imageSrc(draft[field])} alt={draft[prefix+'Alt']||''}/>{/if}<h2>{draft.title||draft.name}</h2>{#if kind==='article'}<p class="lead">{draft.intro}</p><ArticleBody article={{...getArticles(atlasArticles).map(enrichAtlasArticle).find(a=>'article:'+a.slug===key)!,...draft}} compact/><div class="fact-box">{draft.fact}</div>{:else if kind==='wine'}<p>{draft.producer}</p><p>{draft.region} · {draft.grape}</p><span class="wine-style">{draft.style}</span><p>{draft.hint}</p>{:else}<p>{draft.intro}</p><h3>{draft.heroTitle}</h3><p>{draft.heroText}</p>{/if}</aside></form>{/if}{/if}{/if}
</div>
<Modal bind:open={picker} title="Bild auswählen"><div class="media-picker"><p class="muted">Wähle ein vorhandenes Bild oder lade ein neues hoch.</p><div class="media-grid">{#each media as m}<button type="button" aria-label={m.alt} onclick={()=>choose(m)}><img src={m.url} alt={m.alt} loading="lazy"/><span>{m.alt}</span></button>{/each}</div><form class="upload-form" onsubmit={e=>{e.preventDefault();upload();}}><h3>Neues Bild hochladen</h3><label>Bilddatei <small>JPG, PNG, WebP oder AVIF · höchstens 3 MB</small><input bind:this={uploadFile} type="file" accept="image/jpeg,image/png,image/webp,image/avif" required/></label><label>Was zeigt das Bild?<input bind:value={uploadAlt} required maxlength="400"/></label><label>Bildnachweis<input bind:value={uploadCredit} maxlength="400"/></label><label>Quellenadresse<input type="url" bind:value={uploadSource}/></label>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}<button class="button primary" disabled={busy}>{busy?'Wird hochgeladen …':'Bild hochladen'}</button></form></div></Modal>
